static bool waitFor(const std::function<bool()> &f,int ms=15000){QElapsedTimer t;t.start();while(!f()&&t.elapsed()<ms){QCoreApplication::processEvents();QThread::msleep(3);}return f();}
static void settle(int ms=250){QElapsedTimer t;t.start();waitFor([&]{return t.elapsed()>=ms;},ms+1000);}
static bool put(const QString &p,const QString &s){QFile f(p);return f.open(QIODevice::WriteOnly)&&f.write(s.toUtf8())==s.toUtf8().size();}
static QString read(const QString &p){QFile f(p);return f.open(QIODevice::ReadOnly)?QString::fromUtf8(f.readAll()).replace("\r\n","\n"):QString();}
static bool completeCaption(QToolButton *button){
 const auto actual=button->window()->grab(QRect(button->mapTo(button->window(),QPoint()),button->size())).toImage().convertToFormat(QImage::Format_RGB32);QImage expected(actual.size(),QImage::Format_RGB32);expected.fill(Qt::white);expected.setDevicePixelRatio(actual.devicePixelRatio());
 {QPainter painter(&expected);painter.setFont(button->font());painter.setPen(Qt::black);painter.drawText(button->rect(),Qt::AlignCenter,button->text());}
 auto inkRows=[](const QImage &image){int rows=0;const int inset=qRound(4*image.devicePixelRatio());for(int y=inset;y<image.height()-inset;++y){bool ink=false;for(int x=inset;x<image.width()-inset;++x){const auto pixel=image.pixel(x,y);if(qMax(qRed(pixel),qMax(qGreen(pixel),qBlue(pixel)))<170){ink=true;break;}}rows+=ink;}return rows;};
 return inkRows(actual)>=inkRows(expected)-1;
}
